function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function hasAnyLink(value, ids) {
  const links = asLinks(value);
  return links.some((id) => ids.includes(id));
}

function getString(value) {
  return String(value || "").trim();
}

function getNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function round(value) {
  return Math.round(value * 10) / 10;
}

function lower(value) {
  return getString(value).toLowerCase();
}

function isTeacher(user) {
  const role = lower(user.fields.Rol);
  return role === "ogretmen" || role === "öğretmen";
}

function isActiveClass(classRecord) {
  const status = lower(classRecord.fields.Durum);
  return status !== "pasif" && status !== "arsivlendi" && status !== "arşivlendi";
}

function isActiveStudentMembership(membership) {
  const role = lower(membership.fields.Uyelik_Rolu);
  const status = lower(membership.fields.Durum);

  const isStudent = role === "ogrenci" || role === "öğrenci";
  return isStudent && status === "aktif";
}

function isPendingMembership(membership) {
  return lower(membership.fields.Durum) === "onay bekliyor";
}

function isPublishedAssignment(assignment) {
  const status = lower(assignment.fields.Durum);
  return status !== "taslak" && status !== "arsivlendi" && status !== "arşivlendi";
}

function isSubmissionGraded(submission) {
  const status = lower(submission.fields.Durum);
  const score = getNumber(submission.fields.Puan);

  return (
    status === "degerlendirildi" ||
    status === "değerlendirildi" ||
    score !== null
  );
}

function isPresentAttendance(attendance) {
  const status = lower(attendance.fields.Durum);
  return status === "geldi" || status === "gec geldi" || status === "geç geldi";
}

function calculateGradeAverage(grades) {
  const percentages = grades
    .map((grade) => {
      const score = getNumber(grade.fields.Puan);
      const maxScore = getNumber(grade.fields.Maksimum_Puan) || 100;

      if (score === null || maxScore <= 0) return null;

      return (score / maxScore) * 100;
    })
    .filter((value) => value !== null);

  if (percentages.length === 0) return null;

  return round(percentages.reduce((sum, value) => sum + value, 0) / percentages.length);
}

function calculateRiskScore({ gradeAverage, submissionRate, attendanceRate }) {
  let score = 0;

  if (gradeAverage === null) score += 15;
  else if (gradeAverage < 50) score += 40;
  else if (gradeAverage < 60) score += 32;
  else if (gradeAverage < 70) score += 22;
  else if (gradeAverage < 80) score += 10;

  if (submissionRate === null) score += 5;
  else score += (100 - submissionRate) * 0.25;

  if (attendanceRate === null) score += 5;
  else score += (100 - attendanceRate) * 0.25;

  return Math.max(0, Math.min(100, round(score)));
}

function riskCategory(score) {
  if (score >= 85) return "Kritik";
  if (score >= 70) return "Yüksek";
  if (score >= 50) return "Orta";
  return "Düşük";
}

const dateNode = $items("Set Weekly Date Range")[0]?.json || {};

const weekStart =
  dateNode.weekStart ||
  $now.setZone("Europe/Istanbul").startOf("week").toISODate();

const weekEnd =
  dateNode.weekEnd ||
  $now.setZone("Europe/Istanbul").startOf("week").plus({ days: 6 }).toISODate();

const users = getRecords("GET Kullanicilar");
const classes = getRecords("GET Siniflar");
const memberships = getRecords("GET Sinif_Uyelikleri");
const assignments = getRecords("GET Odevler");
const submissions = getRecords("GET Odev_Teslimleri");
const grades = getRecords("GET Notlar");
const attendanceRecords = getRecords("GET Yoklamalar");
const attendanceSessions = getRecords("GET Yoklama_Oturumlari");

const teachers = users.filter(isTeacher);
const output = [];

for (const teacher of teachers) {
  const teacherId = teacher.id;
  const teacherName = getString(teacher.fields.Ad_Soyad) || "Öğretmen";
  const teacherEmail = getString(teacher.fields.Eposta);

  const teacherClasses = classes.filter((classRecord) => {
    return isActiveClass(classRecord) && hasAnyLink(classRecord.fields.Ogretmen, [teacherId]);
  });

  const classIds = teacherClasses.map((classRecord) => classRecord.id);

  const classMemberships = memberships.filter((membership) =>
    hasAnyLink(membership.fields.Sinif, classIds)
  );

  const activeMemberships = classMemberships.filter(isActiveStudentMembership);
  const pendingMemberships = classMemberships.filter(isPendingMembership);

  const activeStudentIds = Array.from(
    new Set(
      activeMemberships.flatMap((membership) => asLinks(membership.fields.Kullanici))
    )
  );

  const teacherAssignments = assignments.filter((assignment) => {
    return (
      isPublishedAssignment(assignment) &&
      (hasAnyLink(assignment.fields.Ogretmen, [teacherId]) ||
        hasAnyLink(assignment.fields.Sinif, classIds))
    );
  });

  const assignmentIds = teacherAssignments.map((assignment) => assignment.id);

  const teacherSubmissions = submissions.filter((submission) =>
    hasAnyLink(submission.fields.Odev, assignmentIds)
  );

  const ungradedSubmissions = teacherSubmissions.filter(
    (submission) => !isSubmissionGraded(submission)
  );

  const teacherAttendanceSessions = attendanceSessions.filter((session) =>
    hasAnyLink(session.fields.Sinif, classIds)
  );

  const teacherAttendanceRecords = attendanceRecords.filter((attendance) =>
    hasAnyLink(attendance.fields.Sinif, classIds)
  );

  const teacherGrades = grades.filter((grade) => {
    return hasAnyLink(grade.fields.Ogretmen, [teacherId]) || hasAnyLink(grade.fields.Sinif, classIds);
  });

  const studentSummaries = activeStudentIds.map((studentId) => {
    const student = users.find((user) => user.id === studentId);
    const studentName = getString(student?.fields?.Ad_Soyad) || "Öğrenci";

    const studentMemberships = activeMemberships.filter((membership) =>
      hasAnyLink(membership.fields.Kullanici, [studentId])
    );

    const studentClassIds = Array.from(
      new Set(studentMemberships.flatMap((membership) => asLinks(membership.fields.Sinif)))
    );

    const studentAssignments = teacherAssignments.filter((assignment) =>
      hasAnyLink(assignment.fields.Sinif, studentClassIds)
    );

    const studentAssignmentIds = studentAssignments.map((assignment) => assignment.id);

    const studentSubmissions = teacherSubmissions.filter((submission) => {
      return (
        hasAnyLink(submission.fields.Ogrenci, [studentId]) &&
        hasAnyLink(submission.fields.Odev, studentAssignmentIds)
      );
    });

    const submissionRate =
      studentAssignments.length > 0
        ? round((studentSubmissions.length / studentAssignments.length) * 100)
        : null;

    const studentGrades = teacherGrades.filter((grade) =>
      hasAnyLink(grade.fields.Ogrenci, [studentId])
    );

    const gradeAverage = calculateGradeAverage(studentGrades);

    const studentAttendanceSessions = teacherAttendanceSessions.filter((session) =>
      hasAnyLink(session.fields.Sinif, studentClassIds)
    );

    const studentAttendanceRecords = teacherAttendanceRecords.filter((attendance) =>
      hasAnyLink(attendance.fields.Ogrenci, [studentId])
    );

    const presentCount = studentAttendanceRecords.filter(isPresentAttendance).length;

    const attendanceRate =
      studentAttendanceSessions.length > 0
        ? round((presentCount / studentAttendanceSessions.length) * 100)
        : null;

    const riskScore = calculateRiskScore({
      gradeAverage,
      submissionRate,
      attendanceRate,
    });

    const category = riskCategory(riskScore);

    return {
      studentId,
      studentName,
      gradeAverage,
      submissionRate,
      attendanceRate,
      riskScore,
      category,
    };
  });

  const lowRiskCount = studentSummaries.filter((s) => s.category === "Düşük").length;
  const mediumRiskCount = studentSummaries.filter((s) => s.category === "Orta").length;
  const highRiskCount = studentSummaries.filter((s) => s.category === "Yüksek").length;
  const criticalRiskCount = studentSummaries.filter((s) => s.category === "Kritik").length;

  const riskyStudents = studentSummaries
    .filter((s) => s.category !== "Düşük")
    .sort((a, b) => b.riskScore - a.riskScore);

  let mostCommonRiskReason = "Belirgin risk nedeni yok";

  if (riskyStudents.length > 0) {
    const missingSubmissions = riskyStudents.filter(
      (s) => s.submissionRate !== null && s.submissionRate < 70
    ).length;

    const lowAttendance = riskyStudents.filter(
      (s) => s.attendanceRate !== null && s.attendanceRate < 70
    ).length;

    const lowGrades = riskyStudents.filter(
      (s) => s.gradeAverage !== null && s.gradeAverage < 60
    ).length;

    const reasons = [
      { reason: "Ödev teslim oranı düşük", count: missingSubmissions },
      { reason: "Yoklama katılımı düşük", count: lowAttendance },
      { reason: "Not ortalaması düşük", count: lowGrades },
    ].sort((a, b) => b.count - a.count);

    if (reasons[0].count > 0) {
      mostCommonRiskReason = reasons[0].reason;
    } else {
      mostCommonRiskReason = "Veri eksikliği nedeniyle risk oluşuyor";
    }
  }

  const summary = {
    activeClassCount: teacherClasses.length,
    activeStudentCount: activeStudentIds.length,
    pendingJoinRequestCount: pendingMemberships.length,
    assignmentCount: teacherAssignments.length,
    submissionCount: teacherSubmissions.length,
    ungradedSubmissionCount: ungradedSubmissions.length,
    attendanceSessionCount: teacherAttendanceSessions.length,
    attendanceRecordCount: teacherAttendanceRecords.length,
    lowRiskCount,
    mediumRiskCount,
    highRiskCount,
    criticalRiskCount,
    mostCommonRiskReason,
  };

  const reportTitle = `${teacherName} - Haftalık AI Risk Raporu - ${weekStart} / ${weekEnd}`;

  const prompt = `
Sen AkıllıSınıf AI sistemi için Türkçe akademik haftalık rapor hazırlayan ciddi ve profesyonel bir eğitim analitiği asistanısın.

Sadece verilen verileri kullan. Veri uydurma.

Rapor bölümleri:
1. Haftalık Genel Özet
2. Öncelikli Bulgular
3. Risk Analizi
4. Müdahale Önerileri
5. Öğretmen İçin Sonraki Adımlar

Öğretmen: ${teacherName}
E-posta: ${teacherEmail || "Yok"}
Hafta başlangıcı: ${weekStart}
Hafta bitişi: ${weekEnd}

Genel özet:
${JSON.stringify(summary, null, 2)}

Riskli öğrenciler:
${JSON.stringify(riskyStudents.slice(0, 20), null, 2)}
`;

  output.push({
    json: {
      teacherId,
      teacherName,
      teacherEmail,
      classIds,
      primaryClassId: classIds[0] || "",
      reportTitle,
      weekStart,
      weekEnd,
      summary,
      riskyStudents,
      mostCommonRiskReason,
      openRouterBody: {
        model: "openrouter/free",
        messages: [
          {
            role: "system",
            content:
              "Sen Türkçe akademik rapor yazan profesyonel bir eğitim analitiği asistanısın. Ciddi, net ve veri odaklı yaz.",
          },
          {
            role: "user",
            content: prompt,
          },
        ],
        temperature: 0.2,
        max_tokens: 2200,
      },
    },
  });
}

return output;

const aiItems = $input.all();
const sourceItems = $items("Prepare Teacher Weekly Data");

const output = aiItems.map((item, index) => {
  const source = sourceItems[index]?.json || {};

  const aiText =
    item.json.choices?.[0]?.message?.content ||
    "OpenRouter boş yanıt döndürdü. Otomasyon çalıştı ancak AI metni üretilemedi.";

  return {
    json: {
      fields: {
        Rapor_Adi: source.reportTitle,
        Sinif: source.primaryClassId ? [source.primaryClassId] : [],
        Ogretmen: source.teacherId ? [source.teacherId] : [],
        Hafta_Baslangic: source.weekStart,
        Hafta_Bitis: source.weekEnd,
        Toplam_Ogrenci: source.summary?.activeStudentCount || 0,
        Dusuk_Risk_Sayisi: source.summary?.lowRiskCount || 0,
        Orta_Risk_Sayisi: source.summary?.mediumRiskCount || 0,
        Yuksek_Risk_Sayisi: source.summary?.highRiskCount || 0,
        Kritik_Risk_Sayisi: source.summary?.criticalRiskCount || 0,
        En_Yaygin_Risk_Nedeni:
          source.mostCommonRiskReason || "Belirgin risk nedeni yok",
        Rapor_Metni: aiText,
        Durum: "Hazırlandı",
      },
    },
  };
});

return output;
